#[unsafe(no_mangle)]
pub extern "C" fn rsf_get_runtime_version() -> *const std::ffi::c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}

// C callers can recover from allocation failure. A successful handle is
// released with Box::from_raw after its owner has retired outstanding users.
fn allocate_handle<T>(value: T) -> *mut T {
    const { assert!(size_of::<T>() != 0) }
    let raw = unsafe { std::alloc::alloc(std::alloc::Layout::new::<T>()).cast::<T>() };
    if !raw.is_null() {
        unsafe { raw.write(value) };
    }
    raw
}

#[cfg(windows)]
fn reserve_handle<T>() -> Option<Box<std::mem::MaybeUninit<T>>> {
    let storage = allocate_handle(std::mem::MaybeUninit::<T>::uninit());
    (!storage.is_null()).then(|| unsafe { Box::from_raw(storage) })
}

// Reserve before opening GPU resources. Some failures leave an owner for the caller to retire.
#[cfg(windows)]
fn initialize_handle<T>(
    out: &mut *mut T,
    allocation_error: i32,
    initialize: impl FnOnce() -> (i32, Option<T>),
) -> i32 {
    let Some(storage) = reserve_handle() else {
        return allocation_error;
    };
    let (result, owner) = initialize();
    if let Some(owner) = owner {
        *out = Box::into_raw(Box::write(storage, owner));
    }
    result
}

// Adopt a returned Win32 handle. APIs use both null and -1 to report failure.
#[cfg(windows)]
unsafe fn owned_win32_handle(
    raw: std::os::windows::io::RawHandle,
) -> Option<std::os::windows::io::OwnedHandle> {
    use std::os::windows::io::{FromRawHandle, OwnedHandle};
    use windows_sys::Win32::Foundation::INVALID_HANDLE_VALUE;

    if raw.is_null() || raw == INVALID_HANDLE_VALUE {
        return None;
    }
    Some(unsafe { OwnedHandle::from_raw_handle(raw) })
}

// The performance counter, in its own ticks.
#[cfg(windows)]
fn now_qpc() -> u64 {
    let mut now = 0i64;
    unsafe { windows_sys::Win32::System::Performance::QueryPerformanceCounter(&mut now) };
    now as u64
}

// A copy of a C string the caller may leave null, `fallback` then. `text` is null or a live
// NUL-terminated string.
unsafe fn copy_c_string(text: *const std::ffi::c_char, fallback: &std::ffi::CStr) -> std::ffi::CString {
    if text.is_null() {
        fallback.to_owned()
    } else {
        unsafe { std::ffi::CStr::from_ptr(text) }.to_owned()
    }
}

// One more reference to a COM object the caller may leave null. `object` is null or live.
#[cfg(windows)]
unsafe fn retain_object(object: *mut std::ffi::c_void) -> Option<windows::core::IUnknown> {
    (!object.is_null()).then(|| unsafe { com_ref::retain(object) })
}
use crate::sys::{RSF_SR_DLSS, RSF_SR_FSR3, RSF_SR_NONE, RSF_SR_XESS};

#[unsafe(no_mangle)]
pub extern "C" fn rsf_gpu_default_sr_backend(vendor: u32, software: u32) -> u32 {
    if software != 0 {
        return RSF_SR_NONE;
    }
    match vendor {
        0x10de => RSF_SR_DLSS,
        0x8086 => RSF_SR_XESS,
        _ => RSF_SR_FSR3,
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn rsf_gpu_select_sr_backend(vendor: u32, software: u32, choices: u32) -> u32 {
    let preferred = rsf_gpu_default_sr_backend(vendor, software);
    if preferred == RSF_SR_NONE {
        return RSF_SR_NONE;
    }
    [preferred, RSF_SR_FSR3, RSF_SR_XESS]
        .into_iter()
        .find(|backend| choices & (1 << backend) != 0)
        .unwrap_or(RSF_SR_NONE)
}
